import * as React from "react";
import { CountryIcon } from "../../icon";
import "./StaticCountry.scss";
import { SvgCountryIcon } from "../../../assets/icons";

export interface StaticCountryProps {
  countryIcon?: keyof typeof SvgCountryIcon;
  countryLabel?: React.ReactNode;
}

const StaticCountry: React.FC<StaticCountryProps> = ({
  countryIcon = "SGIcon",
  countryLabel = "+65",
}) => {
  return (
    <div className="static-country-icon-container">
      <CountryIcon iconName={countryIcon} />
      <span className="static-country-label">{countryLabel}</span>
    </div>
  );
};

export default StaticCountry;
